            order.push_back(v);
        }
    }

    // 倍增父亲
    for (int k = 1; k < LOG; k++) {
        for (int i = 1; i <= n; i++) {
            fa[k][i] = fa[k - 1][fa[k - 1][i]];
        }
    }

    // 求子树大小和重儿子
    for (int i = n - 1; i >= 0; i--) {
        int u = order[i];
        sz[u] = 1;

        for (int v : g[u]) {
            if (v == fa[0][u]) continue;

            sz[u] += sz[v];
            if (son[u] == 0 || sz[v] > sz[son[u]]) {
                son[u] = v;
            }
        }
    }
}

// 求 DFS 序
void dfsDfn(int u) {
    dfn[u] = ++timerCnt;
    rev[timerCnt] = u;

    for (int v : g[u]) {
        if (v != fa[0][u]) {
