### Python

```python
import sys
sys.setrecursionlimit(300000)

MOD1 = 1000000007
MOD2 = 1000000009
BASE = 911382323

def solve(n, s, edges):
    g = [[] for _ in range(n + 1)]
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)

    LOG = 18
    fa = [[0] * (n + 1) for _ in range(LOG)]
    dep = [0] * (n + 1)
    size = [1] * (n + 1)
    son = [0] * (n + 1)

    h1 = [0] * (n + 1)
    h2 = [0] * (n + 1)
    pow1 = [1] * (n + 2)
    pow2 = [1] * (n + 2)

    for i in range(1, n + 2):
        pow1[i] = pow1[i - 1] * BASE % MOD1
        pow2[i] = pow2[i - 1] * BASE % MOD2

    order = [1]
    fa[0][1] = 0

    # 建树并求父亲、深度和根到点哈希
    for u in order:
        for v in g[u]:
            if v == fa[0][u]:
                continue
            fa[0][v] = u
            dep[v] = dep[u] + 1
            c = ord(s[v - 1]) - ord('a') + 1
            h1[v] = (h1[u] * BASE + c) % MOD1
            h2[v] = (h2[u] * BASE + c) % MOD2
            order.append(v)

    # 倍增父亲
    for k in range(1, LOG):
        for i in range(1, n + 1):
            fa[k][i] = fa[k - 1][fa[k - 1][i]]

    # 求子树大小和重儿子
    for u in reversed(order):
        size[u] = 1
        for v in g[u]:
            if v == fa[0][u]:
                continue
            size[u] += size[v]
            if size[v] > size[son[u]]:
                son[u] = v

    dfn = [0] * (n + 1)
    rev = [0] * (n + 1)
    timer = 0

    # DFS 序，方便枚举子树
    def dfs_dfn(u):
        nonlocal timer
        timer += 1
        dfn[u] = timer
        rev[timer] = u
        for v in g[u]:
            if v != fa[0][u]:
                dfs_dfn(v)

    dfs_dfn(1)

    ans = [1] * (n + 1)

    # 求 ancestor 到 x 的下一层后到 x 的字符串哈希
    def get_hash(ancestor, x):
        length = dep[x] - dep[ancestor]
        a = ancestor
        v1 = (h1[x] - h1[a] * pow1[length]) % MOD1
        v2 = (h2[x] - h2[a] * pow2[length]) % MOD2
        return v1, v2

    # 枚举子树中的所有节点
    def nodes_in_subtree(u):
        for i in range(dfn[u], dfn[u] + size[u]):
            yield rev[i]

    # 递归处理每个节点
    def dfs(u):
        for v in g[u]:
            if v != fa[0][u]:
                dfs(v)

        mp = {}

        # 先加入重儿子子树，减少总枚举次数
        if son[u]:
            for x in nodes_in_subtree(son[u]):
                d = dep[x] - dep[u]
                key = (d, get_hash(u, x))
                mp[key] = son[u]

        # 处理其他儿子子树
        for v in g[u]:
            if v == fa[0][u] or v == son[u]:
                continue

            # 先查询，避免同一儿子子树内部互相匹配
            for x in nodes_in_subtree(v):
                d = dep[x] - dep[u]
                key = (d, get_hash(u, x))
                if key in mp and mp[key] != v:
                    ans[u] = max(ans[u], 2 * d + 1)

            # 再加入当前儿子子树
            for x in nodes_in_subtree(v):
                d = dep[x] - dep[u]
                key = (d, get_hash(u, x))
                mp[key] = v

    dfs(1)
    return ans[1:]


def main():
    input = sys.stdin.readline
    n = int(input())
    s = input().strip()

    edges = []
    for _ in range(n - 1):
        u, v = map(int, input().split())
        edges.append((u, v))

    ans = solve(n, s, edges)
    print(*ans)


if __name__ == "__main__":
    main()
